<section class="admin-page-head"><div><p class="admin-kicker">M10 · <?= e(Rules::LABELS[$d['status']]) ?></p><h1><?= e($d['folio']) ?></h1><p><?= e($d['customer_name'].' · '.$d['branch_name']) ?></p></div><a class="admin-secondary-button" href="/admin/deliveries">Entregas</a></section>
<section class="admin-panel"><h2>Documento y entrega acordada</h2><p>Cotización <?= e($d['quote_folio']) ?> · versión <?= e($d['version_number']) ?> · <?= e($d['mode']==='pickup'?'Recolección en sucursal':'Entrega a domicilio') ?></p><p>Fecha <?= e($d['scheduled_date']) ?> · Responsable <?= e($d['actor_name']) ?> · Costo acordado MXN <?= e($d['delivery_cost']) ?></p><p><?= e($d['address']) ?> <?= e($d['location_reference']) ?></p><p>Receptor acordado: <?= e($d['receiver']?:'Por confirmar') ?></p><?php if($stop):?><p>Ruta #<?= e($stop['run_id']) ?> · <?= e($stop['run_name']) ?> · Parada <?= e($stop['position']) ?> · Vehículo #<?= e($stop['vehicle_id']) ?> · Repartidor #<?= e($stop['driver_id']) ?></p><?php endif?><p>Preparar no altera inventario. La salida física consume el apartado una sola vez. Confirmar recepción conserva ese movimiento.</p></section>
<section class="admin-panel admin-table-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Mercancía</th><th>Asignada</th><th>Preparada</th><th>Despachada</th><th>Recibida</th><th>Pendiente cliente</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td data-label="Mercancía"><?= e($i['sku'].' · '.$i['description'].' · '.$i['symbol']) ?></td><?php foreach(['quantity'=>'Asignada','prepared_quantity'=>'Preparada','dispatched_quantity'=>'Despachada','received_quantity'=>'Recibida']as $key=>$label):?><td data-label="<?= e($label) ?>"><?= e($i[$key]) ?></td><?php endforeach?><td data-label="Pendiente cliente"><?= e($i['pending_quantity']) ?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="admin-panel"><h2>Pendiente de la cotización</h2><?php foreach($pending as $i):?><p><?= e($i['sku']) ?> · Documentado <?= e($i['quantity']) ?> · Despachado <?= e($i['dispatched_quantity']) ?> · Recibido <?= e($i['received_quantity']) ?> · Pendiente <?= e($i['pending_quantity']) ?> · Sin asignar <?= e($i['unallocated_quantity']) ?></p><?php endforeach?></section>
<?php foreach(Rules::ACTIONS as $action=>$label):if(!$actions[$action])continue;try{Rules::transition($d['status'],$action);}catch(Throwable){continue;}?>
<section class="admin-panel"><h2><?= e($label) ?></h2><form method="post" action="/admin/deliveries/action" class="admin-form" data-delivery-event>
