<?php if(in_array($action,['edit','confirm'],true)):?><div class="admin-form-grid"><?php foreach($items as $i):$max=$action==='edit'?$i['quantity']:$i['pending_receipt'];?><label class="admin-field"><span><?= e($i['sku'].' · '.$i['symbol']) ?> · <?= e($action==='edit'?'Actual':'Pendiente') ?> <?= e($max) ?></span><input name="quantity[<?= e($i['id']) ?>]" inputmode="decimal" value="<?= e($action==='edit'?$max:'0') ?>"></label><?php endforeach?></div><?php endif?>
<?php if($action==='confirm'):?><label class="admin-field"><span>Nombre de quien recibió</span><input name="receiver" maxlength="120" required></label><?php endif?>
<?php if($action==='assign'&&$d['mode']==='home'):?><p>Selecciona una ruta de la misma sucursal y fecha. <a href="/admin/deliveries/resources?kind=delivery_runs">Consultar rutas</a></p><div class="admin-form-grid"><label class="admin-field"><span>ID de ruta</span><input name="run_id" inputmode="numeric" required></label><label class="admin-field"><span>Posición de parada</span><input name="position" inputmode="numeric" required></label></div><?php endif?>
<label class="admin-field"><span>Observaciones <?= in_array($action,['cancel','incident','retry'],true)?'(obligatorias)':'' ?></span><textarea name="notes" maxlength="500" <?= in_array($action,['cancel','incident','retry'],true)?'required minlength="5"':'' ?>></textarea></label>
<?php if(in_array($action,['dispatch','confirm','cancel'],true)):?><label><input type="checkbox" name="physical_confirmation" value="1" required> <?= e($action==='dispatch'?'Confirmo que toda la mercancía preparada sale físicamente.':($action==='confirm'?'Confirmo las cantidades recibidas por el cliente.':'Confirmo la cancelación sin salida física.')) ?></label><?php endif?><button class="admin-primary-button"><?= e($label) ?></button></form></section><?php endforeach?>
<?php if($history):?><section class="admin-panel"><h2>Historial y movimientos M05</h2><ol><?php foreach($history as $h):?><li><strong><?= e((Rules::ACTIONS+['create'=>'Entrega creada'])[$h['action']]??$h['action']) ?></strong> · <?= e($h['actor_name']) ?> · <?= e($h['created_at']) ?> UTC · <?= e(Rules::LABELS[$h['to_status']]??$h['to_status']) ?><p><?= e($h['notes']) ?> <?= e($h['quantity']??'') ?><?php if($h['inventory_movement_id']):?> · Movimiento M05 #<?= e($h['inventory_movement_id']) ?><?php endif?><?php if($h['receiver']):?> · Recibió <?= e($h['receiver']) ?><?php endif?></p><?php if(($canEvidence??false)&&in_array($h['action'],['confirm','incident'],true)):?><a href="/admin/media?kind=evidence&amp;parent_id=<?= e($h['id']) ?>">Fotografías de esta operación</a><?php endif?></li><?php endforeach?></ol></section><?php endif?>
<section class="admin-panel"><p>Un intento fallido conserva la mercancía despachada pendiente de recepción. Para retornos o pérdidas se requiere un procedimiento físico aprobado; cambiar el estado no reintegra stock. Las fotografías se consultan desde cada confirmación o incidencia autorizada.</p></section>
